package com.parevetimer.app;
import android.app.*;import android.content.*;import android.media.AudioAttributes;import android.os.Build;import android.os.VibrationEffect;import android.os.Vibrator;
public final class NotificationHelper{public static final String CHANNEL="timer_finished";private NotificationHelper(){}public static void createChannels(Context c){if(Build.VERSION.SDK_INT>=26){NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);NotificationChannel ch=new NotificationChannel(CHANNEL,"סיום טיימר",NotificationManager.IMPORTANCE_HIGH);ch.setDescription("התראה כשההמתנה מסתיימת");n.createNotificationChannel(ch);}}
 public static void notifyFinished(Context c){createChannels(c);String mode=Prefs.getNotificationMode(c);Intent i=new Intent(c,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(c,81,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CHANNEL):new Notification.Builder(c);b.setSmallIcon(R.drawable.ic_clock).setContentTitle("אני פרווה!").setContentText("זמן ההמתנה הסתיים").setAutoCancel(true).setContentIntent(pi);if(Build.VERSION.SDK_INT<26&&"vibrate".equals(mode))b.setVibrate(new long[]{0,250,150,250});NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);n.notify(9001,b.build());if("vibrate".equals(mode)){Vibrator v=(Vibrator)c.getSystemService(Context.VIBRATOR_SERVICE);if(v!=null){if(Build.VERSION.SDK_INT>=26)v.vibrate(VibrationEffect.createOneShot(450,VibrationEffect.DEFAULT_AMPLITUDE));else v.vibrate(450);}}}
}